/**
 *  A file attached to a received message. Inline images the email shows
 *  itself (`cid:`) aren't listed as attachments.
 */
export type Attachment = {
	id: AttachmentId,
	messageId: MessageId,
	filename: string,
	mimeType: string,
	/**  Bytes, as Gmail reports it. */
	size: number,
};

export type AttachmentId = number;

/**  What Calendar says about the invitation. */
export type CalendarState = 
/**  The account signed in before Mailboat asked for Calendar. */
{ kind: "needsSignIn" } | 
/**  Someone's answer to your invitation: nothing to look up. */
{ kind: "notNeeded" } | { kind: "notOnCalendar" } | { kind: "onCalendar"; eventId: string; yourAnswer: Answer | null; cancelled: boolean; clashes: Clash[]; 
/**  The event in Google Calendar on the web. */
link: string | null } | 
/**  Calendar couldn't be asked (offline, API turned off, …). */
{ kind: "unavailable"; message: string } | 
/**
 *  Calendar couldn't add the event, so the answer went to the
 *  organizer by email (the standard calendar reply).
 */
{ kind: "repliedByEmail"; yourAnswer: Answer };

/**  Gmail's inbox tabs. */
export type Category = "primary" | "social" | "updates" | "forums" | "promotions";

/**  Something on your calendar at the same time. */
export type Clash = {
	title: string | null,
	start: Moment,
	end: Moment | null,
};

/**  Someone compose can suggest, best first in [`all`]. */
export type Contact = {
	name: string | null,
	email: string,
	/**
	 *  You've sent them mail (they rank first; then saved Google
	 *  contacts, then everyone else).
	 */
	wrote: boolean,
};

/**  Which app opens `mailto:` links. */
export type DefaultMailApp = 
/**  This copy of Mailboat. */
{ kind: "this" } | 
/**
 *  Mailboat, but macOS sends links to another copy, at `path`. The
 *  default is kept by bundle ID, which the dev build and the installed
 *  app share, so macOS picks the copy (usually the one in
 *  /Applications); no button here can change that.
 */
{ kind: "otherCopy"; path: string } | 
/**  Another app, by name (Mail, say). */
{ kind: "other"; name: string } | 
/**  Nothing claims mailto links. */
{ kind: "none" } | 
/**  Not on this platform yet. */
{ kind: "unsupported" };

